def guess_divisors(X, queries):
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    answer = 1
    for _ in range(queries):
        query = 1
        while query < 1000:
            current = query
            while current < X:
                current *= query
            current //= gcd(X, query)
            if current < X:
                answer = max(answer, current)
                break
            current //= query
        if answer >= X:
            break

    return answer

