        l, r, p = rule
        if s[:r].count(l) < l.count(l) or s[:r].count(r) > r.count(r):
            return False
    return True

def count_good_substrings(s, rules):
    ans = Counter()
    ans[s[0]] = 1

    for i in range(1, len(s)):
        for l in range(i + 1, len(s) + 1):
            substring = s[i:l]
            ans[substring] += 1
            if is_good_substring(substring, rules):
                ans[substring] += 1

