import sys

def find_shortest_path(graph, start, end):
    stack = [(start, 0)]
    visited = set([start])
    while stack:
        node, distance = stack.pop()
        if node == end:
            return distance
        for neighbor in graph[node]:
            if neighbor not in visited:
                stack.append((neighbor, distance + 1))
                visited.add(neighbor)
    return sys.maxsize

