def max_distinct_museums(n, m, d, schedules):
    graph = defaultdict(set)

    for u_i, v_i in m:
        graph[u_i].add(v_i)

    depth = [-1] * (n + 1)
    visited = set()
    max_depth = [inf] * (n + 1)

    def bfs(start):
        queue = deque([(start, 0)])
        while queue:
            node, depth_ = queue.popleft()
            if node in visited:
                continue
            visited.add(node)
            max_depth[node] = max(max_depth[node], depth_)
            depth[node] = depth_
            for neighbor in graph[node]:
                queue.append((neighbor, depth[node] + 1))

    for i in range(1, n + 1):
        bfs(i)

    result = [0] * d
    for city in schedules:
        for day in range(d):
            if max_depth[city[day]] + 1 < day:
                result[day] -= 1

    d1 = result[0]
    for i in range(1, d):
        d1 += max(result[i])
    if d1 >= 0:
        return d1 + 1
    return 0

