from collections import defaultdict
from itertools import product
from typing import Set

class RuleBasedSubstringProcessor:
    def __init__(self, rules):
        self.string_rules = defaultdict(list)
        for r in rules:
            p, l, r = r.split()
            for length in range(l, r + 1):
                self.string_rules[length].append(p)

    def is_good(self, substring):
        for length in self.string_rules:
            rules = self.string_rules[length]
            found = [0] * len(rules)
            matches = 0
            for start in range(len(substring) - length + 1):
                for p in rules:
                    for i in range(len(p)):
                        if substring[start + i] != p[i] and p[i] != '_':
                            found[start] += 1
                            break
                    if p == substring[start:start + length]:
                        matches += 1
                if matches == length:
                    ones = found.count(1)
                    if ones > 0 and ones < length:
                        return True
            if matches < length:
                return False
        return True

    def find_good_substrings(self, s):
        substrings = set(s[i:j] for i, j in product(range(len(s) + 1), repeat=2))
        good_substrings = set()
        for length in self.string_rules:
            if length > len(s):
                break
            for p in self.string_rules[length]:
                s_start = 0
                for p_start, c in enumerate(p):
                    if c == '_':
                        possible_substrings = set()
                        while s_start + length - p_start <= len(s):
                            possible_substrings.add(s[s_start:s_start + length])
                            s_start += 1
                        if [is_blocked for is_blocked in possible_substrings if self.is_good(p[0:p_start])] == [False,
                                                                                                               True]:
                            good_substrings.add(p[0:p_start] + p[p_start:p_start + length])
                    else:
                        good_substrings.add(p)
        return len(good_substrings)


