def huffman_encoding(lengths):
    max_heap = []
    for length in lengths:
        heappush(max_heap, (-length, length))
    while len(max_heap) > 1:
        freq1, char1 = heappop(max_heap)
        freq2, char2 = heappop(max_heap)
        combined_freq = -freq1 + -freq2
        heapq.heappush(max_heap, (combined_freq, [char1, char2]))
    encoding = defaultdict(str)
    visited = set()
    encoding_dict = {}
    def build_tree(root, prefix=''):
        if root[1] == '' or root[1] == ' ':
            encoding[root[-1]] = prefix + '0'
        else:
            forward = root[0]
            back = root[1]
            temp = build_tree(root[2:], prefix + '1')
            encoding[forward] = temp
            encoding[back] = temp
            visited.add(temp)
        return 'a'
    build_tree(max_heap[0][2:], '')
    return encoding

def huffman_coding(char_length, encoding):
    def encoding_code(char_length, cargo, encoding):
        for char, element in encoding.items():
            if cargo == char:
                yield element
    return defaultdict(encoding_code)

def query_function(char_length, encoding, lower_bound, upper_bound):
    encoded_output = []
    for j in range(len(char_length)):
        for i in range(1, len(char_length) - j):
            if sum(char_length[i:i + j + 1]) <= upper_bound:
                encoded_output.extend(encoding[char_length[i:i + j + 1]])
    return ''.join(*encoded_output)

