def count_ways(N, A):
    MOD = 998244353
    # Initialize the parity variables
    is_even, ans = 0, 0
    for x in A:
        if not (x % 2):
            if not is_even:
                is_even = 'even'
        else:
            if 'odd' in ('even', 'odd'):
                ans += 1
                is_even = 'even'
            else:
                is_even = 'odd'
    # If no subarrays, return 1
    if not A:
        return 1
    # If only one element, it can't make the pattern
    if len(A) == 1:
        return 0
    # If the array sum is odd, start from 1 and increment
    if sum(A) % 2 == 1:
        return (ans + min(N - 1, 1)) % MOD
    # Otherwise, start from 0 (return 0 if odd-sum at start for even sum, vice versa)
    return (ans + min(N - 1, 1) - 1 if N > 2 else ans) % MOD

