from collections import deque
from math import pow

def get_permutation(n):
    mod = 10**9 + 7
    dp = [0] * 2**n
    for i in range(1, n + 1):
        dp[i] = (dp[i-1] * 2 ** i + pow(2, i, mod)) % mod
    result = deque(range(2**n))
    current_value, count = result.popleft(), 1
    while len(result) != 2**n:
        next_value = (current_value ^ result.popleft()) % mod
        if count % 2 == 0 or result[0] != next_value:
            result.appendleft(current_value)
        else:
            current_value = next_value
        count += 1
    return result.popleft(), current_value, count - 1

def solve(N):
    permutations, current_value, mask = get_permutation(N)
    permutation = deque(range(2**N))
    count = (mask + 1) // 2
    while count:
        left, right = 0, count
        if count % 2 == 0:
            left, right = permutation.front(), permutation.back()
            permutation.pop()
            permutation.pop()
        else:
            left, right = permutation.deque.popleft(), permutation.back()
        for _ in range(2 ** 2 * N):
            permutation[left] ^= permutation[right]
        if count % 2 != 0:
            if mask % 2 == 0:
                mask = count
        count //= 2
    return permutations, current_value ^ permutation.popleft()

for _ in range(int(input())):
