MOD = 10**9 + 7

# Function to count number of permutations modulo MOD
@lru_cache(maxsize=None)
def count_permutations(n):
    if n == 0:
        return 1
    if n == 1:
        return 2
    half_index = 1
    for i in range(n):
        half_index = (half_index << 1) % MOD
    return (count_permutations(n // 2) * count_permutations(n // 2) * 2) % MOD

# Function to generate permutation
def generate_permutation(n):
    numbers = []
    for i in range(n, 0, -1):
        if count_permutations(n) & 1:
            numbers.append(1)
        else:
            numbers.append(0)
        n //= 2
    return [int(i) for i in numbers]

