def max_depth(node, depth):
    if node.children:
        max_child_depth = depth
        for child in node.children:
            child_depth = depth
            max_child_depth = max(max_child_depth, max_depth(child, child_depth + 1))
        max_depth = max(max_depth, max_child_depth)
        return max_depth
    else:
        return max_depth

def process_queries(n, q, description):
