from collections import defaultdict, deque

def min_max_distance(n, k, edges):
    if k > 1:
        # Build the graph
        graph = defaultdict(list)
        for u, v, d in edges:
            graph[u].append((v, d))
            graph[v].append((u, d))

        # Initialize distances from each junction to all other junctions
        distances = [[float('inf')] * n for _ in range(n)]
        for u in range(n):
            distances[u] = [distance[u] for distance in distances]

        # Perform BFS to get the shortest distances from each junction to all other junctions
        for u in range(n):
            visited = [False] * n
            queue = deque([(u, 0)])
            while queue:
                curr = queue.popleft()
                if visited[curr[0]]:
                    continue
                visited[curr[0]] = True
                distances[curr[0]][curr[1]] = curr[1]
                for neighbor, weight in graph[curr[0]]:
                    if not visited[neighbor] and distances[curr[0]][0] + weight < distances[neighbor][0]:
                        distances[neighbor][0] = distances[curr[0]][0] + weight
                        queue.append((neighbor, distances[neighbor][0]))

        # Find the minimal possible maximum distance
        return min(distances[u][k - 1] for u in range(n))
    else:
        # If only one shop, it must be a point (there can't be a path)
        return float('inf')

# Read input
n, k = map(int, input().split())
edges = [tuple(map(int, input().split())) for _ in range(n - 1)]

# Output the result
print(min_max_distance(n, k, edges))
