from collections import defaultdict

def flip_string(s, i, j):
    """Swap characters at i and j indices in the string s."""
    s = list(s)
    s[i], s[j] = s[j], s[i]
    return ''.join(s)

def max_length_path_length(root):
    """Calculate the maximum length of a simple path in the binary tree rooted at root."""
    if not root:
        return (0, 0)

    lengths = defaultdict(lambda: (0, 0))
    for i, color in enumerate(root):
        if not i:
            lengths[i] = (1, 2)  # For the root, both children are initially left to make it balanced
        elif color == '-':
            lengths[i] = (lengths[i-1][0], lengths[i-1][1] + 2)  # Flood fill the left subtree first
        else:
            lengths[i] = (lengths[i+1][0], lengths[i+1][1] + 2)  # Then the right subtree

    max_length = max(lengths.values())
    non_leaf_length = max_length[0]
    return max_length, non_leaf_length

def diameter_of_new_tree(descriptions):
    """Given the initial root description, return the diameter of all trees after various flips."""
    max_diameter = 0
    for description_flipped in descriptions:
        _, non_leaf_diameter = max_length_path_length(description_flipped)
        if non_leaf_diameter > max_diameter:
            max_diameter = non_leaf_diameter
        flip_string_list = description_flipped.split()
        for i in range(len(flip_string_list)):
            flip_string_list[i] = flip_string(flip_string_list, i, i+1)
        clicked_diameters = [max_length_path_length(flip_string(flip_string_list, i, i+1)) for i in range(len(flip_string_list) - 1)]
        max_diameter = max(max([x[0] for x in clicked_diameters]), max_diameter)
    return max_diameter

