from collections import Counter

def is_good(s, rules):
    for rule in rules:
        p, l, r = rule
        if all(s.find(sub) == -1 or s.find(sub, i, i + len(sub)) >= l and s.find(sub, i, i + len(sub)) <= r for sub in p):
            return False
    return True

def count_good_substrings(s, rules):
    n = len(s)
    substr_counts = Counter()
    for i, char in enumerate(s):
        substr_counts.update(''.join(sorted(s[i:])), count=1)
    for symbol in substr_counts:
        for i in range(1, n + 1):
            for j in range(i, n + 1):
                substr = s[i:j]
                if is_good(substr, rules):
                    substr_counts[substr] += 1
    return len(substr_counts)

