import sys

def max_travelling_time():
    n, m = map(int, input().split())
    roads = []
    for _ in range(n - 1):
        v, u, w = map(int, input().split())
        roads.append((w, v, u))
    roads.sort()
    x = map(int, input().split())
    dp = [0] * n
    for w, v, u in roads:
        if v < u:
            v, u = u, v
        for i in range(n):
            if dp[i] < w:
                dp[i] = w
    result = [0] * m
    for i, x_val in enumerate(x):
        max_val = 0
        for j in range(n):
            max_val = max(max_val, dp[j])
        result[i] = max_val + x_val
    for val in result:
